CREATE TABLE IF NOT EXISTS abbreviations (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, category TEXT NOT NULL, category_slug TEXT NOT NULL, meaning_bn TEXT NOT NULL, description_bn TEXT NOT NULL, icon TEXT NOT NULL DEFAULT '📖', tag TEXT NOT NULL DEFAULT '', created_at TEXT, updated_at TEXT);
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('SBL','Smart Business Link','E-Commerce Core','ecommerce','এসবিএল ই-কমার্স ও ড্রপশিপিং ইকোসিস্টেম','SBL হলো একটি পূর্ণাঙ্গ বিজনেস প্ল্যাটফর্ম যা ড্রপশিপিং, মার্চেন্ট নেটওয়ার্ক ও মেম্বার পোর্টাল পরিচালনা করে।','🌐','Ecosystem');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('COD','Cash On Delivery','E-Commerce Core','ecommerce','পণ্য হাতে পেয়ে মূল্য পরিশোধের ডেলিভারি ব্যবস্থা','গ্রাহক পণ্য গ্রহণের সময় কুরিয়ার রাইডারকে সম্পূর্ণ মূল্য পরিশোধ করে থাকেন। বাংলাদেশে প্রায় ৯০% সেলস সিওডিতে হয়।','💵','Payment');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('SKU','Stock Keeping Unit','E-Commerce Core','ecommerce','পণ্যের অনন্য শনাক্তকরণ কোড','ইনভেন্টরিতে প্রতিটি পণ্যের সাইজ, রঙ বা মডেল আলাদাভাবে ট্র্যাক করার জন্য ব্যবহৃত ইউনিক আলফানিউমেরিক কোড।','🏷️','Inventory');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('AOV','Average Order Value','E-Commerce Core','ecommerce','গড় অর্ডার মূল্য','মোট বিক্রয় আয়কে মোট অর্ডার সংখ্যা দিয়ে ভাগ করে AOV বের করা হয় (মোট বিক্রয় ÷ মোট অর্ডার)।','📊','Revenue');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('MOQ','Minimum Order Quantity','E-Commerce Core','ecommerce','সর্বনিম্ন অর্ডার পরিমাণ','কোনো সাপ্লায়ার বা প্রস্তুতকারক থেকে সোর্সিং করার সর্বনিম্ন সংখ্যা। ড্রপশিপিংয়ে সাধারণত MOQ থাকে না।','📦','Sourcing');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('B2B','Business to Business','E-Commerce Core','ecommerce','এক ব্যবসা প্রতিষ্ঠান থেকে অন্য ব্যবসায়ের লেনদেন','সাপ্লায়ার বা প্রস্তুতকারক যখন সরাসরি ড্রপশিপার, মার্চেন্ট বা হোলসেলারের কাছে পণ্য বিক্রি করে।','🏢','Model');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('B2C','Business to Consumer','E-Commerce Core','ecommerce','ব্যবসা প্রতিষ্ঠান থেকে সরাসরি ভোক্তার কাছে বিক্রি','ড্রপশিপার যখন ফেসবুক পেজ বা ওয়েবসাইটের মাধ্যমে সরাসরি সাধারণ খুচরা ক্রেতার নিকট পণ্য বিক্রি করে।','🛍️','Model');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('D2C','Direct to Consumer','E-Commerce Core','ecommerce','মধ্যস্বত্বভোগী ছাড়া সরাসরি নিজস্ব ব্র্যান্ড থেকে বিক্রয়','কোনো থার্ড-পার্টি মার্কেটপ্লেসের উপর নির্ভর না করে নিজস্ব ওয়েবসাইট/ফানেলে সরাসরি ক্রেতার কাছে সেলস।','🎯','Brand');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('MR','Merchant Reseller','E-Commerce Core','ecommerce','মার্চেন্ট রিসেলার বা ড্রপশিপ পার্টনার','এসবিএল প্ল্যাটফর্মের রেজিস্টার্ড রিসেলার যিনি নিজস্ব মূলধন ও ইনভেন্টরি ছাড়া পণ্য বিপণন করে প্রফিট মার্জিন আয় করেন।','🤝','Partner');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('RTO','Return To Origin','Logistics & Delivery','logistics','ডেলিভারি ব্যর্থ হয়ে পণ্য মার্চেন্টের ঠিকানায় ফেরত আসা','কাস্টমার পণ্য রিসিভ না করলে বা ফোন না ধরলে কুরিয়ার পার্সেলটি পুনরায় সোর্স ওয়্যারহাউসে ফেরত পাঠায়। ড্রপশিপিংয়ে RTO রেট কমানো অন্যতম প্রধান কাজ।','🔄','Courier');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('NDR','Non-Delivery Report','Logistics & Delivery','logistics','পার্সেল ডেলিভারি ব্যর্থ হওয়ার কারণ সম্বলিত রিপোর্ট','কুরিয়ার রাইডার কাস্টমারের কাছে যেতে না পারলে বা কাস্টমার ডেলিভারি স্থগিত রাখতে বললে কুরিয়ার পোর্টালে এনডিআর রেইজ করা হয়।','⚠️','Courier');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('AWB','Air Waybill / Consignment Tracking Number','Logistics & Delivery','logistics','কুরিয়ার কনসাইনমেন্ট ট্র্যাকিং নম্বর','প্রতিটি পার্সেলের গায়ে লাগানো বারকোড নম্বর যার মাধ্যমে কাস্টমার ও মার্চেন্ট পার্সেলের লাইভ অবস্থান ট্র্যাক করতে পারে।','🚚','Tracking');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('3PL','Third-Party Logistics','Logistics & Delivery','logistics','তৃতীয় পক্ষ লজিস্টিক ও কুরিয়ার সার্ভিস প্রোভাইডার','বহিরাগত লজিস্টিক কোম্পানি যা গুদামজাতকরণ, প্যাকেজিং এবং ডোর-টু-ডোর ডেলিভারি সেবা পরিচালনা করে (যেমন: Steadfast, RedX, Paperfly)।','📦','Logistics');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('TAT','Turnaround Time','Logistics & Delivery','logistics','অর্ডার প্লেস থেকে কাস্টমারের হাতে পৌঁছানোর মোট সময়','অর্ডার কনফার্মেশনের পর থেকে কুরিয়ার কর্তৃক সফল ডেলিভারি পর্যন্ত অতিবাহিত মোট কর্মঘণ্টা বা দিনের হিসাব।','⏱️','Speed');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('SLA','Service Level Agreement','Logistics & Delivery','logistics','কুরিয়ার ও মার্চেন্টের মধ্যকার সেবা প্রদান চুক্তির সময়সীমা','কুরিয়ার কত ঘণ্টার মধ্যে পার্সেল পিকআপ ও ডেলিভারি করবে তার চুক্তিভিত্তিক প্রতিশ্রুতি।','📝','Standard');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('POD','Proof of Delivery','Logistics & Delivery','logistics','পণ্য সফলভাবে হস্তান্তরের ডিজিটাল প্রমাণ বা সাক্ষ্য','কাস্টমার পণ্য বুঝে পাওয়ার পর দেওয়া ডিজিটাল স্বাক্ষর, ওটিপি বা রিসিভ কনফার্মেশন।','✅','Delivery');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('ROAS','Return On Ad Spend','Marketing & Ads','marketing','বিজ্ঞাপন খরচের বিপরীতে বিক্রয় আয় অনুপাত','ক্যাম্পেইনে প্রতি ১ টাকা বিজ্ঞাপনে কত টাকা রেভিনিউ আসল (মোট বিক্রয় আয় ÷ বিজ্ঞাপন খরচ)। যেমন: ৫০০০ টাকা খরচ করে ২০০০০ টাকার সেল আসলে ROAS = 4X।','🎯','Efficiency');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CPA','Cost Per Acquisition / Action','Marketing & Ads','marketing','প্রতিটি সফল অর্ডার বা বিক্রয় অর্জনের বিজ্ঞাপন খরচ','মোট বিজ্ঞাপনের বাজেটকে মোট সফল অর্ডারের সংখ্যা দিয়ে ভাগ করে সিপিএ নির্ণয় করা হয় (Ad Spend ÷ Total Orders)।','💳','Cost');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CPM','Cost Per Mille (Per 1,000 Impressions)','Marketing & Ads','marketing','বিজ্ঞাপন ১,০০০ বার প্রদর্শনের খরচ','ফেসবুক বা গুগলে ১০০০ জন মানুষের ফিডে আপনার বিজ্ঞাপন পৌঁছানোর জন্য প্ল্যাটফর্ম যে খরচ চার্জ করে।','👁️','Impression');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CPC','Cost Per Click','Marketing & Ads','marketing','বিজ্ঞাপনে প্রতিটি ক্লিকে হওয়া গড় খরচ','কাস্টমার বিজ্ঞাপনে ক্লিক করে ল্যান্ডিং পেজে যাওয়ার জন্য ফেসবুক যে চার্জ কাটে (Ad Spend ÷ Total Clicks)।','🖱️','Traffic');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CTR','Click-Through Rate','Marketing & Ads','marketing','বিজ্ঞাপন দেখে ক্লিক করার শতকরা হার','(ক্লিক সংখ্যা ÷ ইম্প্রেশন) × ১০০। বিজ্ঞাপনের কপি, ছবি বা ভিডিও কতটা আকর্ষণীয় হয়েছে তা CTR দ্বারা পরিমাপ করা হয়। ড্রপশিপিংয়ে ২%+ CTR ভালো ধরা হয়।','📈','Performance');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CVR','Conversion Rate','Marketing & Ads','marketing','ভিজিটরের অর্ডারে রূপান্তরের শতকরা হার','(মোট অর্ডার সংখ্যা ÷ মোট ল্যান্ডিং পেজ ভিজিটর) × ১০০। সাইটে ১০০ জন আসলে ৩ জন অর্ডার করলে কনভার্সন রেট ৩%।','🛒','Conversion');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('LP','Landing Page','Marketing & Ads','marketing','একটি নির্দিষ্ট পণ্যের একক সেলস ওয়েবপেজ','বিজ্ঞাপনে ক্লিক করার পর কাস্টমার সরাসরি যে পেজে প্রবেশ করে এবং যেখানে পণ্যের রিভিউ, বিবরণ ও অর্ডার ফর্ম থাকে।','📄','Web');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('UGC','User Generated Content','Marketing & Ads','marketing','গ্রাহকদের নিজ হাতে তৈরি ছবি, আনবক্সিং বা রিভিউ ভিডিও','প্রফেশনাল বিজ্ঞাপনের চেয়ে সাধারণ কাস্টমারের আনবক্সিং ও রিভিউ ভিডিও দ্বারা বিজ্ঞাপনে কনভার্সন রেট অনেক বেশি বৃদ্ধি পায়।','📱','Creative');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CAC','Customer Acquisition Cost','Marketing & Ads','marketing','একজন নতুন গ্রাহক পাওয়ার সার্বিক খরচ','বিজ্ঞাপন, টুলস ও টিম খরচ মিলিয়ে একজন পেইড কাস্টমার সংগ্রহ করার মোট খরচ।','👥','Finance');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('LTV','Lifetime Value (CLV)','Marketing & Ads','marketing','একজন গ্রাহকের আজীবন ক্রয়মূল্য বা লাইফটাইম ভ্যালু','একজন গ্রাহক প্রথমবার কেনার পর ভবিষ্যতে পুনরায় আপনার কাছ থেকে মোট যত টাকার পণ্য কেনে তার সামগ্রিক মূল্য।','💎','Retention');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('BV','Business Volume','SBL Network & System','network','কমিশন ও বোনাস গণনার মূল বিজনেস পয়েন্ট','এসবিএল সিস্টেমে পণ্য ও প্যাকেজ বিক্রয়ের উপর ভিত্তি করে নির্ধারিত বিজনেস ভলিউম, যা অনুযায়ী পেয়ার ও ম্যাচিং বোনাস হিসাব হয়।','⚡','Commission');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('PV','Point Value','SBL Network & System','network','প্যাকেজ বা প্রোডাক্ট পয়েন্ট মান','প্রতিটি প্রোডাক্ট বা মেম্বারশিপ প্যাকেজে নির্দিষ্ট পয়েন্ট থাকে যা মেম্বারদের র‍্যাংক আপগ্রেডেশন ও ইনসেন্টিভের জন্য কাউন্ট হয়।','⭐','Points');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('KYC','Know Your Customer','SBL Network & System','network','গ্রাহক ও মেম্বারের পরিচয় সত্যতা যাচাইকরণ','জাতীয় পরিচয়পত্র (NID) ও মোবাইল নম্বর যাচাই করে ভেরিফায়েড মেম্বার হিসেবে অ্যাকাউন্ট একটিভ করার প্রক্রিয়া।','🛡️','Security');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('MB','Matching Bonus','SBL Network & System','network','বাইনারি টিমের লেফট ও রাইট ম্যাচিং বোনাস','বাইনারি ট্রিতে লেফট সাইড এবং রাইট সাইডে সেলস পয়েন্ট সমানুপাতিকভাবে ম্যাচ হলে মেম্বারের অ্যাকাউন্টে স্বয়ংক্রিয়ভাবে জমা হওয়া বোনাস।','⚖️','Bonus');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('GB','Generation Bonus','SBL Network & System','network','টিমের বিভিন্ন প্রজন্ম বা স্তর থেকে প্রাপ্ত প্রফিট শেয়ার','সরাসরি স্পনসরকৃত ডাউনলাইন ও তাদের তৈরি নেটওয়ার্কের সক্রিয় পারফরম্যান্স থেকে প্রাপ্ত রয়্যালটি বা জেনারেশন ইনকাম।','🌳','Bonus');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('ROI','Return On Investment','SBL Network & System','network','বিনিয়োগকৃত মূলধনের বিপরীতে প্রাপ্ত নিট মুনাফা','এসবিএল ক্রাউডফান্ডিং বা ড্রপশিপিং প্যাকেজে প্রদত্ত মূলধনের বিপরীতে সাপ্তাহিক বা মাসিক অর্জিত লভ্যাংশ।','💰','Investment');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('OTP','One-Time Password','SBL Network & System','network','এককালীন ব্যবহারযোগ্য নিরাপত্তা পাসওয়ার্ড','ব্যালেন্স উইথড্রয়াল, পাসওয়ার্ড পরিবর্তন বা স্পর্শকাতর অ্যাকশন অনুমোদনের সময় মোবাইলে আসা গোপন কোড।','🔐','Security');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('COGS','Cost Of Goods Sold','Finance & Operations','finance','পণ্য প্রস্তুত বা ক্রয়ের প্রত্যক্ষ খরচ','বিজ্ঞাপন ছাড়া সরাসরি পণ্যটি সাপ্লায়ার থেকে কিনতে যে পরিমাণ খরচ হয়েছে। (বিক্রয় মূল্য - COGS = গ্রস প্রফিট)।','🧾','Accounting');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('P&L','Profit and Loss Statement','Finance & Operations','finance','লাভ ও ক্ষতির সামগ্রিক আর্থিক হিসাব বিবরণী','নির্দিষ্ট সময়ের মোট আয়, পণ্য ক্রয় খরচ, বিজ্ঞাপন ও কুরিয়ার রিটার্ন খরচ বাদ দিয়ে নিট লাভের স্টেটমেন্ট।','📉','Finance');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('MFS','Mobile Financial Services','Finance & Operations','finance','মোবাইল ব্যাংকিং আর্থিক সেবা চ্যানেল','বিকাশ, নগদ বা রকেটের মাধ্যমে কমিশন উইথড্রয়াল ও মার্চেন্ট পেমেন্ট সেটেলমেন্ট চ্যানেল।','📲','Payment');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('POS','Point Of Sale','Finance & Operations','finance','বিক্রয় ও ক্যাশ কাউন্টার সিস্টেম','ইনস্ট্যান্ট বিলিং, ইনভয়েস জেনারেশন ও বারকোড রিড করার বিক্রয় সফটওয়্যার।','🖥️','Software');
